#[derive(Parser)]
#[command(version = "0.9.9", about = "A smarter cd command")]
#[command(author = "Ajeet D'Souza <98ajeet@gmail.com>")]
#[command(args_conflicts_with_subcommands = true)]
struct Cli {
    #[command(subcommand)]
    command: Option<Command>,

