enum Command {
    /// Add a new directory or increment its rank
    Add {
        #[arg(value_name = "PATHS")]
        paths: Vec<String>,

        /// The rank to increment the entry if it exists or initialize it with if it doesn't
        #[arg(short, long)]
        score: Option<f64>,
    },

    /// Search for a directory in the database
    Query {
        #[arg(value_name = "KEYWORDS")]
        keywords: Vec<String>,

        /// Show unavailable directories
        #[arg(short, long)]
        all: bool,

        /// Use interactive selection
        #[arg(short, long)]
        interactive: bool,

        /// List all matching directories
        #[arg(short, long)]
        list: bool,

        /// Print score with results
        #[arg(short, long)]
        score: bool,

        /// Exclude the current directory
        #[arg(long)]
        exclude: Option<String>,

        /// Only search within this directory
        #[arg(long)]
        base_dir: Option<String>,
    },

    /// Remove a directory from the database
    Remove {
        #[arg(value_name = "PATHS")]
        paths: Vec<String>,
    },

    /// Generate shell configuration
    Init {
        /// Shell to generate configuration for
        shell: String,

        /// Prevents zoxide from defining the `z` and `zi` commands
        #[arg(long)]
        no_cmd: bool,

        /// Changes the prefix of the `z` and `zi` commands
        #[arg(long, default_value = "z")]
        cmd: String,

        /// Changes how often zoxide increments a directory's score
        #[arg(long, default_value = "pwd")]
        hook: String,
    },

    /// Edit the database
    Edit,

    /// Import entries from another application
    Import {
        /// Application to import from
        #[arg(long)]
        from: String,

        /// Path to the database to import from
        #[arg(value_name = "PATH")]
        path: String,

        /// Merge into existing database
        #[arg(long)]
        merge: bool,
    },
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    // Handle subcommands
    match cli.command {
        Some(Command::Add { paths, score }) => {
            add::run(paths, score)?;
        }
        Some(Command::Query { keywords, all, interactive, list, score, exclude, base_dir }) => {
            query::run(keywords, all, interactive, list, score, exclude, base_dir)?;
        }
        Some(Command::Remove { paths }) => {
            remove::run(paths)?;
        }
        Some(Command::Init { shell, no_cmd, cmd, hook }) => {
            init::run(&shell, no_cmd, &cmd, &hook)?;
        }
        Some(Command::Edit) => {
            edit::run()?;
        }
        Some(Command::Import { from, path, merge }) => {
            import::run(&from, &path, merge)?;
        }
        None => {
            // No subcommand provided, show help
            if !cli.args.is_empty() {
                eprintln!("unknown command: {}", cli.args[0]);
                eprintln!("For more information try --help");
                process::exit(1);
            }
            println!("{}", Cli::command().render_help());
        }
    }

    Ok(())
}
