use anyhow::{anyhow, Result};
use serde::{Deserialize, Serialize};
use std::fs::File;
use std::io::{Read, Write, BufReader, BufWriter};
use std::path::{Path, PathBuf};
use std::collections::HashMap;
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Entry {
    pub path: String,
    pub freq: f64,
    pub timestamp: i64,
}

pub struct Database {
    pub entries: Vec<Entry>,
}

impl Database {
    pub fn new() -> Self {
        Database {
            entries: Vec::new(),
        }
    }

    pub fn load_or_create(path: &Path) -> Result<Self> {
        if path.exists() {
            Self::load(path)
        } else {
            Ok(Database::new())
        }
    }

    pub fn load(path: &Path) -> Result<Self> {
        let file = File::open(path)?;
        let mut reader = BufReader::new(file);

        // Read header
        let mut header = [0u8; 12];
        reader.read_exact(&mut header)?;

        let num_entries = u32::from_le_bytes([header[0], header[1], header[2], header[3]]) as usize;
        // Skip header2 and header3

        let mut entries = Vec::with_capacity(num_entries);

        for _ in 0..num_entries {
            // Read path_len
            let mut path_len_bytes = [0u8; 4];
            reader.read_exact(&mut path_len_bytes)?;
            let path_len = u32::from_le_bytes(path_len_bytes) as usize;

            // Read reserved (4 bytes)
            let mut reserved = [0u8; 4];
            reader.read_exact(&mut reserved)?;

            // Read path
            let mut path_bytes = vec![0u8; path_len];
            reader.read_exact(&mut path_bytes)?;
            let path = String::from_utf8(path_bytes)?;

            // Read freq (f64 = 8 bytes)
            let mut freq_bytes = [0u8; 8];
            reader.read_exact(&mut freq_bytes)?;
            let freq = f64::from_le_bytes(freq_bytes);

            // Read timestamp (i64 = 8 bytes)
            let mut ts_bytes = [0u8; 8];
            reader.read_exact(&mut ts_bytes)?;
            let timestamp = i64::from_le_bytes(ts_bytes);

            entries.push(Entry {
                path,
                freq,
                timestamp,
            });
        }

        Ok(Database { entries })
    }

    pub fn save(&self, path: &Path) -> Result<()> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }

        let file = File::create(path)?;
        let mut writer = BufWriter::new(file);

        // Write header
        let num_entries = self.entries.len() as u32;
        writer.write_all(&num_entries.to_le_bytes())?;
        writer.write_all(&num_entries.to_le_bytes())?;  // header2 = num_entries
        writer.write_all(&0u32.to_le_bytes())?;         // header3 = 0

        // Write entries
        for entry in &self.entries {
            let path_bytes = entry.path.as_bytes();
            let path_len = path_bytes.len() as u32;

            writer.write_all(&path_len.to_le_bytes())?;
            writer.write_all(&0u32.to_le_bytes())?;  // reserved = 0
            writer.write_all(path_bytes)?;
            writer.write_all(&entry.freq.to_le_bytes())?;
            writer.write_all(&entry.timestamp.to_le_bytes())?;
        }

        Ok(())
    }

    pub fn get_data_dir() -> Result<PathBuf> {
        if let Ok(data_dir) = std::env::var("_ZO_DATA_DIR") {
            return Ok(PathBuf::from(data_dir));
        }

        let home = std::env::var("HOME")
            .map_err(|_| anyhow!("HOME environment variable not set"))?;

        #[cfg(target_os = "macos")]
        {
            Ok(PathBuf::from(home).join("Library/Application Support/zoxide"))
        }
        #[cfg(target_os = "windows")]
        {
            let localappdata = std::env::var("LOCALAPPDATA")
                .unwrap_or_else(|_| home.clone());
            Ok(PathBuf::from(localappdata).join("zoxide"))
        }
        #[cfg(not(any(target_os = "macos", target_os = "windows")))]
        {
            let xdg_data_home = std::env::var("XDG_DATA_HOME")
                .unwrap_or_else(|_| format!("{}/.local/share", home));
            Ok(PathBuf::from(xdg_data_home).join("zoxide"))
        }
    }

    pub fn get_db_path() -> Result<PathBuf> {
        Ok(Self::get_data_dir()?.join("db.zo"))
    }

    pub fn find(&self, path: &str) -> Option<&Entry> {
        self.entries.iter().find(|e| e.path == path)
    }

    pub fn find_mut(&mut self, path: &str) -> Option<&mut Entry> {
        self.entries.iter_mut().find(|e| e.path == path)
    }

    pub fn add_or_update(&mut self, path: String, score: f64) {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs() as i64;

        if let Some(entry) = self.find_mut(&path) {
            entry.freq += score * 4.0;  // Multiply by 4 for consistency with original
            entry.timestamp = now;
        } else {
            self.entries.push(Entry {
                path,
                freq: score * 4.0,
                timestamp: now,
            });
        }
    }

    pub fn remove(&mut self, path: &str) {
        self.entries.retain(|e| e.path != path);
    }

    pub fn sort_by_frequency(&mut self) {
        self.entries.sort_by(|a, b| {
            b.freq.partial_cmp(&a.freq).unwrap_or(std::cmp::Ordering::Equal)
        });
    }
}
