use anyhow::{anyhow, Result};
use crate::db::Database;
use std::path::Path;

pub fn run(
    keywords: Vec<String>,
    all: bool,
    interactive: bool,
    list: bool,
    score_flag: bool,
    exclude: Option<String>,
    base_dir: Option<String>,
) -> Result<()> {
    let db_path = Database::get_db_path()?;
    let mut db = Database::load_or_create(&db_path)?;

    if keywords.is_empty() && !list {
        return Err(anyhow!("no match found"));
    }

    // Filter entries
    let mut results: Vec<_> = db.entries.iter().collect();

    // Apply exclude filter
    if let Some(exclude_path) = exclude {
        results.retain(|e| e.path != exclude_path);
    }

    // Apply base_dir filter
    if let Some(base) = base_dir {
        results.retain(|e| e.path.starts_with(&base));
    }

    // Apply availability filter (if not --all)
    if !all {
        results.retain(|e| Path::new(&e.path).exists());
    }

    // Match keywords
    if !keywords.is_empty() {
        results.retain(|entry| {
            let path = &entry.path;
            let components: Vec<&str> = path.split('/').collect();

            for keyword in &keywords {
                if keyword == "/" {
                    // This is a prefix match indicator
                    continue;
                }

                let matches = components.iter().any(|comp| comp.contains(keyword));
                if !matches {
                    return false;
                }
            }

            true
        });
    }

    if results.is_empty() {
        return Err(anyhow!("no match found"));
    }

    // Sort by frequency
    results.sort_by(|a, b| {
        b.freq.partial_cmp(&a.freq).unwrap_or(std::cmp::Ordering::Equal)
    });

    if list {
        for entry in results {
            if score_flag {
                println!("{:7.1} {}", entry.freq, entry.path);
            } else {
                println!("{}", entry.path);
            }
        }
    } else {
        if let Some(entry) = results.first() {
            if std::env::var("_ZO_ECHO").ok() == Some("1".to_string()) {
                eprintln!("{}", entry.path);
            }
            println!("{}", entry.path);
        }
    }

    Ok(())
}
