use anyhow::{anyhow, Result};
use crate::db::Database;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

pub fn run(from: &str, path: &str, merge: bool) -> Result<()> {
    let mut db = if merge {
        Database::load_or_create(&Database::get_db_path()?)?
    } else {
        Database::new()
    };

    let file = File::open(path)?;
    let reader = BufReader::new(file);

    match from {
        "autojump" => {
            for line in reader.lines() {
                let line = line?;
                let parts: Vec<&str> = line.split('\t').collect();
                if parts.len() >= 2 {
                    let path_str = parts[0].to_string();
                    if let Ok(freq) = parts[1].parse::<f64>() {
                        db.add_or_update(path_str, freq);
                    }
                }
            }
        }
        "z" => {
            for line in reader.lines() {
                let line = line?;
                let parts: Vec<&str> = line.split('|').collect();
                if parts.len() >= 2 {
                    let path_str = parts[0].to_string();
                    if let Ok(freq) = parts[1].parse::<f64>() {
                        db.add_or_update(path_str, freq);
                    }
                }
            }
        }
        _ => {
            return Err(anyhow!("unknown format: {}", from));
        }
    }

    db.save(&Database::get_db_path()?)?;
    Ok(())
}
