use crate::db::Database;
use std::path::Path;

pub fn run(args: &[String]) -> Result<(), String> {
    let mut paths = Vec::new();
    let mut score = 1.0;
    let mut i = 0;

    while i < args.len() {
        match args[i].as_str() {
            "--score" | "-s" => {
                i += 1;
                if i >= args.len() {
                    return Err("--score requires a value".to_string());
                }
                score = args[i].parse().map_err(|_| format!("invalid score: {}", args[i]))?;
            }
            "--help" | "-h" => {
                print_help();
                return Ok(());
            }
            "--version" | "-V" => {
                println!("zoxide-add 0.9.9");
                return Ok(());
            }
            arg if !arg.starts_with('-') => {
                paths.push(arg.to_string());
            }
            _ => {}
        }
        i += 1;
    }

    if paths.is_empty() {
        return Err("no paths provided".to_string());
    }

    for path_str in paths {
        let path = std::fs::canonicalize(&path_str)
            .unwrap_or_else(|_| std::path::PathBuf::from(&path_str));

        if !path.exists() {
            return Err(format!("not a directory: {}", path_str));
        }

        let db_path = Database::get_db_path()?;
        let mut db = Database::load_or_create(&db_path)?;

        let path_str = path.to_string_lossy().to_string();
        db.add_or_update(path_str, score);

        db.save(&db_path)?;
    }

    Ok(())
}

