    println!("Options:");
    println!("  -s, --score <SCORE>  The rank to increment the entry if it exists or initialize it with if it doesn't");
    println!("  -h, --help           Print help");
    println!("  -V, --version        Print version");
    println!();
    println!("Environment variables:");
