pub fn run(args: &[String]) -> Result<(), String> {
    let mut shell = String::new();
    let mut no_cmd = false;
    let mut cmd = "z".to_string();
    let mut hook = "pwd".to_string();
    let mut i = 0;

    while i < args.len() {
        match args[i].as_str() {
            "--no-cmd" => no_cmd = true,
            "--cmd" => {
                i += 1;
                if i >= args.len() {
                    return Err("--cmd requires a value".to_string());
                }
                cmd = args[i].clone();
            }
            "--hook" => {
                i += 1;
                if i >= args.len() {
                    return Err("--hook requires a value".to_string());
                }
                hook = args[i].clone();
            }
            "--help" | "-h" => {
                print_help();
                return Ok(());
            }
            "--version" | "-V" => {
                println!("zoxide-init 0.9.9");
                return Ok(());
            }
            arg if !arg.starts_with('-') => {
                shell = arg.to_string();
            }
            _ => {}
        }
        i += 1;
    }

    if shell.is_empty() {
        return Err("shell argument required".to_string());
    }

    match shell.as_str() {
        "bash" => print_bash_init(&cmd, &hook),
        "zsh" => print_bash_init(&cmd, &hook),
        "fish" => print_fish_init(&cmd),
        "posix" => print_posix_init(&cmd, &hook),
        "powershell" => println!("# PowerShell initialization stub"),
        "elvish" => println!("# Elvish initialization stub"),
        "tcsh" => print_posix_init(&cmd, &hook),
        "xonsh" => print_posix_init(&cmd, &hook),
        "nushell" => println!("# Nushell initialization stub"),
        _ => return Err(format!("unknown shell: {}", shell)),
    }

    Ok(())
}

fn print_bash_init(cmd: &str, hook: &str) {
    println!("# shellcheck shell=bash\n");
    println!("# =============================================================================");
    println!("#");
    println!("# Utility functions for zoxide.");
    println!("#");
    println!();

    println!("# pwd based on the value of _ZO_RESOLVE_SYMLINKS.");
    println!("function __zoxide_pwd() {{");
    println!("    \\builtin pwd -L");
    println!("}}");
    println!();

    println!("# cd + custom logic based on the value of _ZO_ECHO.");
    println!("function __zoxide_cd() {{");
    println!("    # shellcheck disable=SC2164");
    println!("    \\builtin cd -- \"$@\"");
    println!("}}");
    println!();

    println!("# =============================================================================");
    println!("#");
    println!("# Hook configuration for zoxide.");
    println!("#");
    println!();

    println!("# Hook to add new entries to the database.");
    println!("__zoxide_oldpwd=\"$(__zoxide_pwd)\"");
    println!();

    println!("function __zoxide_hook() {{");
    println!("    \\builtin local -r retval=\"$?\"");
    println!("    \\builtin local pwd_tmp");
    println!("    pwd_tmp=\"$(__zoxide_pwd)\"");
    println!("    if [[ \"${{__zoxide_oldpwd}}\" != \"${{pwd_tmp}}\" ]]; then");
    println!("        \\builtin hash -r");
    println!("        \\command zoxide add -- \"${{pwd_tmp}}\"");
    println!("    fi");
    println!("    __zoxide_oldpwd=\"${{pwd_tmp}}\"");
    println!("    return ${{retval}}");
    println!("}}");
    println!();

    match hook {
        "pwd" => {
            println!("# Initialize hook.");
            println!("[[ \"${{PROMPT_COMMAND[@]}}\" == *\"__zoxide_hook\"* ]] || {{");
            println!("    PROMPT_COMMAND+=(\"__zoxide_hook\")");
            println!("}}");
        }
        "prompt" => {
            println!("# Initialize hook.");
            println!("if [[ -z \"${{PROMPT_COMMAND}}\" ]]; then");
            println!("    PROMPT_COMMAND=\"__zoxide_hook\"");
            println!("elif [[ \"${{PROMPT_COMMAND}}\" != *\"__zoxide_hook\"* ]]; then");
            println!("    PROMPT_COMMAND+=\"; __zoxide_hook\"");
            println!("fi");
        }
        _ => {}
    }
    println!();

    println!("# =============================================================================");
    println!("#");
    println!("# Commands for zoxide.");
    println!("#");
    println!();

    println!("function __zoxide_z() {{");
    println!("    if [[ \"$#\" -eq 0 ]]; then");
    println!("        __zoxide_cd ~");
    println!("    elif [[ \"$1\" == '-' ]] && [[ -n \"$OLDPWD\" ]]; then");
    println!("        __zoxide_cd \"$OLDPWD\"");
    println!("    else");
    println!("        local result");
    println!("        result=\"$(\\command zoxide query --exclude \"$(__zoxide_pwd)\" -- \"$@\")\" && __zoxide_cd \"$result\"");
    println!("    fi");
    println!("}}");
    println!();

    println!("function __zoxide_zi() {{");
    println!("    local result");
    println!("    result=\"$(\\command zoxide query --interactive -- \"$@\")\" && __zoxide_cd \"$result\"");
    println!("}}");
    println!();

    println!("alias {}=__zoxide_z", cmd);
    println!("alias {}i=__zoxide_zi", cmd);
}

fn print_fish_init(cmd: &str) {
    println!("# =============================================================================");
    println!("#");
    println!("# Utility functions for zoxide.");
    println!("#");
    println!();

    println!("# pwd based on the value of _ZO_RESOLVE_SYMLINKS.");
    println!("function __zoxide_pwd");
    println!("    builtin pwd -L");
    println!("end");
    println!();

    println!("# =============================================================================");
    println!("#");
    println!("# Hook configuration for zoxide.");
    println!("#");
    println!();

    println!("function __zoxide_hook --on-variable PWD");
    println!("    command zoxide add -- (builtin pwd -L)");
    println!("end");
    println!();

    println!("# =============================================================================");
    println!("#");
    println!("# Commands for zoxide.");
    println!("#");
    println!();

    println!("function {}; __zoxide_z $argv; end", cmd);
    println!("function {}i; __zoxide_zi $argv; end", cmd);
    println!();

    println!("function __zoxide_z");
    println!("    set argc (count $argv)");
    println!("    if test \"$argc\" -eq 0");
    println!("        builtin cd ~");
    println!("    else if test \"$argv[1]\" = \"-\" -a -n \"$OLDPWD\"");
    println!("        builtin cd \"$OLDPWD\"");
    println!("    else");
    println!("        builtin cd (command zoxide query --exclude (builtin pwd -L) -- $argv)");
    println!("    end");
    println!("end");
    println!();

    println!("function __zoxide_zi");
    println!("    builtin cd (command zoxide query --interactive -- $argv)");
    println!("end");
}

fn print_posix_init(cmd: &str, hook: &str) {
    println!("# shellcheck shell=posix");
    println!();

    println!("# =============================================================================");
    println!("#");
    println!("# Utility functions for zoxide.");
    println!("#");
    println!();

    println!("# pwd based on the value of _ZO_RESOLVE_SYMLINKS.");
    println!("__zoxide_pwd() {{");
    println!("    pwd -L");
    println!("}}");
    println!();

    println!("# cd + custom logic based on the value of _ZO_ECHO.");
    println!("__zoxide_cd() {{");
    println!("    cd \"$@\"");
    println!("}}");
    println!();

    println!("# =============================================================================");
    println!("#");
    println!("# Hook configuration for zoxide.");
    println!("#");
    println!();

    println!("__zoxide_hook() {{");
    println!("    command zoxide add -- \"$(pwd -L)\"");
    println!("}}");
    println!();

    if hook == "prompt" {
        println!("# =============================================================================");
        println!("#");
        println!("# Initialize hook.");
        println!("#");
        println!();
        println!("__zoxide_prompt_old=\"$PS1\"");
        println!("__zoxide_prompt_new=\"__zoxide_hook; $__zoxide_prompt_old\"");
        println!("PS1=\"$__zoxide_prompt_new\"");
    }
    println!();

    println!("# =============================================================================");
    println!("#");
    println!("# Commands for zoxide.");
    println!("#");
    println!();

    println!("__zoxide_z() {{");
    println!("    if [ \"$#\" -eq 0 ]; then");
    println!("        __zoxide_cd ~");
    println!("    elif [ \"$1\" = \"-\" ] && [ -n \"$OLDPWD\" ]; then");
    println!("        __zoxide_cd \"$OLDPWD\"");
    println!("    else");
    println!("        __zoxide_cd \"$(command zoxide query --exclude \"$(pwd -L)\" -- \"$@\")\"");
    println!("    fi");
    println!("}}");
    println!();

    println!("__zoxide_zi() {{");
    println!("    __zoxide_cd \"$(command zoxide query --interactive -- \"$@\")\"");
    println!("}}");
    println!();

    println!("{}() {{ __zoxide_z \"$@\"; }}", cmd);
    println!("{}i() {{ __zoxide_zi \"$@\"; }}", cmd);
}

fn print_help() {
    println!("zoxide-init 0.9.9");
    println!("Ajeet D'Souza <98ajeet@gmail.com>");
    println!("https://github.com/ajeetdsouza/zoxide");
    println!();
    println!("Generate shell configuration");
    println!();
    println!("Usage:");
