            println!("# Initialize hook.");
            println!("if [[ -z \"${{PROMPT_COMMAND}}\" ]]; then");
            println!("    PROMPT_COMMAND=\"__zoxide_hook\"");
            println!("elif [[ \"${{PROMPT_COMMAND}}\" != *\"__zoxide_hook\"* ]]; then");
