    println!("    if [[ \"$#\" -eq 0 ]]; then");
    println!("        __zoxide_cd ~");
    println!("    elif [[ \"$1\" == '-' ]] && [[ -n \"$OLDPWD\" ]]; then");
    println!("        __zoxide_cd \"$OLDPWD\"");
    println!("    else");
    println!("        local result");
    println!("        result=\"$(\\command zoxide query --exclude \"$(__zoxide_pwd)\" -- \"$@\")\" && __zoxide_cd \"$result\"");
    println!("    fi");
    println!("}}");
    println!();

    println!("function __zoxide_zi() {{");
    println!("    local result");
    println!("    result=\"$(\\command zoxide query --interactive -- \"$@\")\" && __zoxide_cd \"$result\"");
    println!("}}");
    println!();

    println!("alias {}=__zoxide_z", cmd);
    println!("alias {}i=__zoxide_zi", cmd);
