use crate::db::Database;
use std::fs::File;
use std::io::{BufRead, BufReader};

pub fn run(args: &[String]) -> Result<(), String> {
    let mut from = String::new();
    let mut path = String::new();
    let mut merge = false;
    let mut i = 0;

    while i < args.len() {
        match args[i].as_str() {
            "--from" => {
                i += 1;
                if i >= args.len() {
                    return Err("--from requires a value".to_string());
                }
                from = args[i].clone();
            }
            "--merge" => merge = true,
            "--help" | "-h" => {
                println!("zoxide-import 0.9.9");
                return Ok(());
            }
            "--version" | "-V" => {
                println!("zoxide-import 0.9.9");
                return Ok(());
            }
            arg if !arg.starts_with('-') => {
                path = arg.to_string();
            }
            _ => {}
        }
        i += 1;
    }

    if from.is_empty() {
        return Err("--from is required".to_string());
    }
    if path.is_empty() {
        return Err("path argument required".to_string());
    }

    let mut db = if merge {
        Database::load_or_create(&Database::get_db_path()?)?
    } else {
        Database::new()
    };

    let file = File::open(&path).map_err(|e| format!("failed to open: {}", e))?;
    let reader = BufReader::new(file);

    match from.as_str() {
        "autojump" => {
            for line in reader.lines() {
                let line = line.map_err(|e| format!("read error: {}", e))?;
                let parts: Vec<&str> = line.split('\t').collect();
                if parts.len() >= 2 {
                    let path_str = parts[0].to_string();
                    if let Ok(freq) = parts[1].parse::<f64>() {
                        db.add_or_update(path_str, freq);
                    }
                }
            }
        }
        "z" => {
            for line in reader.lines() {
                let line = line.map_err(|e| format!("read error: {}", e))?;
                let parts: Vec<&str> = line.split('|').collect();
                if parts.len() >= 2 {
                    let path_str = parts[0].to_string();
                    if let Ok(freq) = parts[1].parse::<f64>() {
                        db.add_or_update(path_str, freq);
                    }
                }
            }
        }
        _ => {
            return Err(format!("unknown format: {}", from));
        }
    }

    db.save(&Database::get_db_path()?)?;
    Ok(())
}
